<?php $balance=max(0,(float)$invoice['total']-(float)$invoice['paid_amount']); ?>
<div class="page-head"><div><a class="back-link" href="<?= e(url('invoices')) ?>">→ <?= e(tr('بازگشت به فاکتورها','Back to invoices')) ?></a><div class="title-with-status"><h1 dir="ltr"><?= e($invoice['invoice_number']) ?></h1><span class="badge <?= badge_class($invoice['status']) ?>"><?= e(status_text($invoice['status'])) ?></span></div><p><?= e(tr('صادرشده برای','Issued to')) ?> <a href="<?= e(url('user-detail',['id'=>$invoice['local_user_id']])) ?>" dir="ltr"><?= e($invoice['username']) ?></a></p></div><button type="button" class="button ghost" onclick="window.print()">▣ <?= e(tr('چاپ','Print')) ?></button></div>
<div class="content-grid half invoice-layout"><section class="panel invoice-paper"><div class="invoice-brand"><span class="brand-mark">UM</span><div><strong><?= e(config('app','name')) ?></strong><small><?= e(tr('صورتحساب خدمات اینترنت','Internet service invoice')) ?></small></div></div><dl class="detail-list"><div><dt><?= e(tr('مشترک','Subscriber')) ?></dt><dd><?= e($invoice['full_name']?:$invoice['username']) ?></dd></div><div><dt><?= e(tr('پلن','Plan')) ?></dt><dd><?= e($invoice['plan_name']?:'—') ?></dd></div><div><dt><?= e(tr('تاریخ صدور','Issue date')) ?></dt><dd><?= e($invoice['issue_date']) ?></dd></div><div><dt><?= e(tr('سررسید','Due date')) ?></dt><dd><?= e($invoice['due_date']) ?></dd></div></dl><div class="invoice-totals"><div><span><?= e(tr('مبلغ','Amount')) ?></span><strong><?= money($invoice['amount'],$invoice['currency']?:'IRR') ?></strong></div><div><span><?= e(tr('تخفیف','Discount')) ?></span><strong><?= money($invoice['discount'],$invoice['currency']?:'IRR') ?></strong></div><div><span><?= e(tr('مالیات','Tax')) ?></span><strong><?= money($invoice['tax'],$invoice['currency']?:'IRR') ?></strong></div><div class="grand"><span><?= e(tr('مبلغ کل','Grand total')) ?></span><strong><?= money($invoice['total'],$invoice['currency']?:'IRR') ?></strong></div><div><span><?= e(tr('پرداخت‌شده','Paid')) ?></span><strong class="success-text"><?= money($invoice['paid_amount'],$invoice['currency']?:'IRR') ?></strong></div><div><span><?= e(tr('مانده','Balance')) ?></span><strong class="<?= $balance>0?'danger-text':'' ?>"><?= money($balance,$invoice['currency']?:'IRR') ?></strong></div></div><?php if($invoice['notes']):?><div class="invoice-notes"><?= nl2br(e($invoice['notes'])) ?></div><?php endif;?></section>
<div class="side-stack"><?php if(Auth::canWrite()&&$balance>0):?><section class="panel"><div class="panel-head"><div><h2><?= e(tr('ثبت پرداخت','Record payment')) ?></h2><p><?= e(tr('حداکثر مانده قابل پرداخت','Maximum balance')) ?>: <?= money($balance,$invoice['currency']?:'IRR') ?></p></div></div><form method="post" class="stack-form"><?= csrf_field() ?><label><span><?= e(tr('مبلغ','Amount')) ?></span><input type="number" name="amount" min="0.01" max="<?= e($balance) ?>" step="0.01" value="<?= e($balance) ?>" required></label><label><span><?= e(tr('روش پرداخت','Payment method')) ?></span><select name="method"><option value="cash"><?= e(tr('نقدی','Cash')) ?></option><option value="bank_transfer"><?= e(tr('انتقال بانکی','Bank transfer')) ?></option><option value="online_gateway"><?= e(tr('درگاه آنلاین','Online gateway')) ?></option></select></label><label><span><?= e(tr('شماره پیگیری','Reference')) ?></span><input name="reference"></label><label><span><?= e(tr('یادداشت','Notes')) ?></span><textarea name="notes" rows="2"></textarea></label><button class="button primary wide"><?= e(tr('ثبت پرداخت','Save payment')) ?></button></form></section><?php endif;?>
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('تاریخچه پرداخت','Payment history')) ?></h2></div></div><div class="payment-list"><?php foreach($payments as $payment):?><div><span class="payment-icon">✓</span><span><strong><?= money($payment['amount'],$invoice['currency']?:'IRR') ?></strong><small><?= e($payment['method']) ?> · <?= e($payment['received_at']) ?></small></span></div><?php endforeach;?><?php if(!$payments):?><p class="empty"><?= e(tr('پرداختی ثبت نشده است.','No payments recorded.')) ?></p><?php endif;?></div></section></div></div>

